                    ctx.collect(new TaskEvent(ts, jobId, taskIndex, eventType));
                } catch (NumberFormatException nfe) {
                    // skip malformed row
                }
            }
        }
    }

    @Override
    public void cancel() {
        running = false;
    }
}
