                .addSource(jobSrc)
                .returns(JobEvent.class)
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((e, ts) -> e.timestampMicros / 1000L));

        // Session windows per job on SUBMIT task events (event_type == 0).
        // Each window emits (jobId, countOfSubmitsInStage).
        SingleOutputStreamOperator<Tuple2<Long, Long>> stageCounts = tasks
                .filter(e -> e.eventType == 0)
                .keyBy((KeySelector<TaskEvent, Long>) e -> e.jobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .aggregate(new CountAgg(), new EmitKeyedCount());

        // Finished jobs: event_type == 4 (FINISH).
        DataStream<Long> finishedJobIds = jobs
                .filter(e -> e.eventType == 4)
                .map(e -> e.jobId)
                .returns(Long.class);

        SingleOutputStreamOperator<String> result = stageCounts
                .keyBy((KeySelector<Tuple2<Long, Long>, Long>) t -> t.f0)
                .connect(finishedJobIds.keyBy((KeySelector<Long, Long>) j -> j))
                .process(new MaxForFinishedJob());

        result.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE).setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    /** AggregateFunction that counts SUBMIT task events in a session. */
    public static class CountAgg implements AggregateFunction<TaskEvent, Long, Long> {
        @Override public Long createAccumulator() { return 0L; }
        @Override public Long add(TaskEvent value, Long acc) { return acc + 1L; }
        @Override public Long getResult(Long acc) { return acc; }
        @Override public Long merge(Long a, Long b) { return a + b; }
    }

    /** Attaches the keyed jobId to the per-window count. */
    public static class EmitKeyedCount
            extends ProcessWindowFunction<Long, Tuple2<Long, Long>, Long, TimeWindow> {
        @Override
        public void process(Long key, Context ctx, Iterable<Long> values,
                            Collector<Tuple2<Long, Long>> out) {
            long count = values.iterator().next();
            out.collect(Tuple2.of(key, count));
        }
    }

    /**
     * Keyed by jobId, consumes per-stage counts and FINISH signals. Flushes at
     * end-of-stream (Long.MAX_VALUE-1 event-time timer) so the max over all stages
     * is only emitted after every event has been observed, matching the "once the
     * job has finished" requirement.
     */
    public static class MaxForFinishedJob
            extends KeyedCoProcessFunction<Long, Tuple2<Long, Long>, Long, String> {

        private transient ValueState<Long> maxCountState;
        private transient ValueState<Boolean> finishedState;
        private transient ValueState<Boolean> timerSetState;

        @Override
        public void open(Configuration parameters) {
            maxCountState = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("maxCount", Long.class));
            finishedState = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("finished", Boolean.class));
            timerSetState = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("timerSet", Boolean.class));
        }

        private void ensureTimer(Context ctx) throws Exception {
            Boolean set = timerSetState.value();
            if (set == null || !set) {
                ctx.timerService().registerEventTimeTimer(Long.MAX_VALUE - 1L);
                timerSetState.update(true);
            }
        }

        @Override
        public void processElement1(Tuple2<Long, Long> value, Context ctx,
                                    Collector<String> out) throws Exception {
            Long cur = maxCountState.value();
            long c = value.f1;
            if (cur == null || c > cur) {
                maxCountState.update(c);
            }
            ensureTimer(ctx);
        }

        @Override
        public void processElement2(Long jobId, Context ctx,
                                    Collector<String> out) throws Exception {
            finishedState.update(true);
            ensureTimer(ctx);
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx,
                            Collector<String> out) throws Exception {
            Boolean finished = finishedState.value();
            Long max = maxCountState.value();
            if (finished != null && finished && max != null) {
                out.collect("(" + ctx.getCurrentKey() + "," + max + ")");
            }
        }
    }
